PythonGoRust <pre><code>"""Price a European Bates option and observe a live spot update."""

# itofin library
from itofin import Settings
from itofin.instruments import OptionType, VanillaOption
from itofin.models import BatesModel
from itofin.pricingengines import BatesEngine
from itofin.processes import BatesProcess
from itofin.quotes import SimpleQuote
from itofin.termstructures import FlatForward
from itofin.time import Date, DayCounter

today = Date(2, 10, 2026)
expiry = Date(2, 10, 2027)
settings = Settings()
settings.set_evaluation_date(today)
dc = DayCounter.actual365_fixed()
spot = SimpleQuote(100.0)
rate = SimpleQuote(0.03)
dividend = SimpleQuote(0.01)
process = BatesProcess(
    spot,
    FlatForward.from_quote(today, rate, dc),
    FlatForward.from_quote(today, dividend, dc),
    0.04, 1.5, 0.04, 0.3, -0.5, 0.7, -0.12, 0.18,
)
model = BatesModel(process)
engine = BatesEngine(model, integration_order=144)
option = VanillaOption(OptionType.Call, 100.0, expiry, settings)
option.set_bates_engine(engine)
print("Bates NPV:", option.npv())
spot.set_value(105.0)
print("After spot update:", option.npv())
print("Calibration parameter order:", model.params())
</code></pre> <pre><code>package main

import (
    "errors"
    "fmt"
    "log"

    itofin "github.com/benbenbang/libitofin/sdk/go"
)

func must[T any](value T, err error) T {
    if err != nil {
        panic(err)
    }
    return value
}

func main() {
    if err := run(); err != nil {
        log.Fatal(err)
    }
}

func run() (err error) {
    s, err := itofin.NewSession()
    if err != nil {
        return err
    }
    defer func() { err = errors.Join(err, s.Close()) }()
    today := must(itofin.NewDate(2, 10, 2026))
    expiry := must(today.AddDays(365))
    settings := must(s.NewSettings())
    if err = settings.SetEvaluationDate(today); err != nil {
        return err
    }
    dc := must(s.Actual365Fixed())
    spot := must(s.NewSimpleQuote(100))
    rate := must(s.NewSimpleQuote(.03))
    dividend := must(s.NewSimpleQuote(.01))
    process := must(s.NewBatesProcess(itofin.BatesProcessConfig{
        Spot:     spot,
        RiskFree: must(s.NewFlatForwardFromQuote(today, rate, dc)),
        Dividend: must(s.NewFlatForwardFromQuote(today, dividend, dc)),
        V0:       .04, Kappa: 1.5, Theta: .04, Sigma: .3, Rho: -.5,
        Lambda: .7, Nu: -.12, Delta: .18,
    }))
    model := must(s.NewBatesModel(process))
    engine := must(s.NewBatesEngine(model, 144))
    option := must(s.NewVanillaOption(itofin.Call, 100, expiry, settings))
    if err = option.SetBatesEngine(engine); err != nil {
        return err
    }
    fmt.Println("Bates NPV:", must(option.NPV()))
    if err = spot.SetValue(105); err != nil {
        return err
    }
    fmt.Println("After spot update:", must(option.NPV()))
    fmt.Println("Calibration parameter order:", must(model.Params()))
    return nil
}
</code></pre> <pre><code>//! Price a European Bates option and observe a live spot update.

use libitofin::errors::QlResult;
use libitofin::exercise::EuropeanExercise;
use libitofin::handle::Handle;
use libitofin::instrument::Instrument;
use libitofin::instruments::{PlainVanillaPayoff, VanillaOption};
use libitofin::interestrate::Compounding;
use libitofin::models::{BatesModel, CalibratedModelHolder};
use libitofin::option::OptionType;
use libitofin::pricingengines::vanilla::BatesEngine;
use libitofin::processes::BatesProcess;
use libitofin::quotes::{Quote, SimpleQuote};
use libitofin::settings::Settings;
use libitofin::shared::{Shared, shared, shared_mut};
use libitofin::termstructures::yields::FlatForward;
use libitofin::termstructures::yieldtermstructure::YieldTermStructure;
use libitofin::time::date::{Date, Month};
use libitofin::time::daycounters::actual365fixed::Actual365Fixed;
use libitofin::time::frequency::Frequency;

fn main() -&gt; QlResult&lt;()&gt; {
    let today = Date::new(2, Month::October, 2026);
    let settings = shared(Settings::&lt;Date&gt;::new());
    settings.set_evaluation_date(today);
    let spot = shared(SimpleQuote::new(100.0));
    let curve = |rate| {
        Handle::new(shared(FlatForward::with_rate(
            today,
            rate,
            Actual365Fixed::new(),
            Compounding::Continuous,
            Frequency::Annual,
        )) as Shared&lt;dyn YieldTermStructure&gt;)
    };
    let process = shared(BatesProcess::new(
        curve(0.03),
        curve(0.01),
        Handle::new(spot.clone() as Shared&lt;dyn Quote&gt;),
        0.04,
        1.5,
        0.04,
        0.3,
        -0.5,
        0.7,
        -0.12,
        0.18,
    )?);
    let model = BatesModel::new(process)?;
    let engine = shared_mut(BatesEngine::new(model.clone(), 144)?);
    let mut option = VanillaOption::new(
        shared(PlainVanillaPayoff::new(OptionType::Call, 100.0)),
        shared(EuropeanExercise::new(today + 365)),
        settings,
    );
    option.base_mut().set_pricing_engine(engine);
    println!("Bates NPV: {}", option.npv()?);
    spot.set_value(105.0);
    println!("After spot update: {}", option.npv()?);
    println!(
        "Calibration parameter order: {:?}",
        model.borrow().calibrated_model().params()
    );
    Ok(())
}
</code></pre> <p>The process retains live spot and yield-curve inputs. The model retains the market, the engine retains the model and the option retains its engine. Updating a quote or model parameter invalidates the cached option value. Go objects must belong to the same session; closing the session ends access.</p>

PythonGo <pre><code>"""Measure the maximum running-peak loss in an ordered positive NAV path."""

# itofin library
from itofin.statistics import maximum_drawdown

result = maximum_drawdown([100.0, 120.0, 90.0, 130.0])
assert (result.drawdown, result.peak_index, result.trough_index) == (0.25, 1, 2)
print(f"maximum drawdown {result.drawdown:.0%}, peak {result.peak_index}, trough {result.trough_index}")
</code></pre> <pre><code>package main

import (
    "fmt"
    itofin "github.com/benbenbang/libitofin/sdk/go"
)

func main() {
    result, err := itofin.MaximumDrawdown([]float64{100, 120, 90, 130})
    if err != nil {
        panic(err)
    }
    if result.Drawdown != 0.25 || result.PeakIndex != 1 || result.TroughIndex != 2 {
        panic("unexpected drawdown")
    }
    fmt.Printf("maximum drawdown %.0f%%, peak %d, trough %d\n", 100*result.Drawdown, result.PeakIndex, result.TroughIndex)
}
</code></pre> <p>From a native-build checkout, run <code>python example/python/drawdown.py</code> or <code>cd sdk/go &amp;&amp; go run ./examples/drawdown</code>.</p>

